import React,{useState,useEffect,useRef} from 'react';
import {useStore} from '../../context/StoreContext';
function reply(message:string,lang:string,catalog:{name:string;sku:string}[]):string {
 const q=message.toLowerCase().trim();const hi=lang==='hi';
 if(/(?:otp|password|cvv|card number|api key|secret)/i.test(q))return hi?'OTP, password ya card details chat mein mat bhejiye. MYSA ko inki zarurat nahi hai.':'Please do not share an OTP, password or card details. MYSA does not need them.';
 if(/order|track|delivery|shipment|status|mera order/i.test(q))return hi?'Order tracking coming soon. Abhi MYSA order records nahi padhti.':'Order tracking is coming soon. MYSA cannot read order records yet.';
 if(/refund|return|cancel|warranty/i.test(q))return hi?'Return/refund policy abhi verify nahi hui hai. Main deadline ya refund ka promise nahi karungi. Store support se policy confirm karein.':'The return/refund policy has not been verified for this chat. I cannot promise a refund, deadline or warranty. Please confirm the policy with store support.';
 if(/support|help|contact|human|madad/i.test(q))return hi?'Main product dhoondhne mein help kar sakti hoon. Yeh chat support ticket ya message nahi bhejta. Udecs.store ke contact section se team tak pahunchein.':'I can help you find products. This chat does not send a support ticket or message. Use the contact section on udecs.store to reach the team.';
 if(/^(hi|hello|hey|namaste|hii|नमस्ते)[!. ]*$/i.test(q))return hi?'Namaste! Main MYSA hoon. Product ka naam ya SKU bhejiye. Main products dhoondhne mein help kar sakti hoon.':'Hi, I am MYSA. Tell me a product name or SKU. I can help you find products.';
 const words=q.split(/\s+/).filter(w=>w.length>2&&!['the','for','show','find','want','price','product','products','mujhe','chahiye','please'].includes(w));
 const matches=catalog.map(p=>({p,score:words.reduce((n,w)=>n+((p.name+' '+p.sku).toLowerCase().includes(w)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);
 if(matches.length)return (hi?'Store catalog mein yeh mile:':'Found these in the store catalog:')+'\n\n'+matches.map(({p})=>p.name+'\nSKU: '+p.sku+'\n').join('\n')+'\n'+(hi?'Current price aur stock udecs.store par confirm karein. Main is chat mein live availability ya payment confirm nahi kar sakti.':'Check current price and stock on udecs.store. I cannot confirm live availability or payment in this chat.');
 return hi?'Is sawaal ka verified jawab abhi mere paas nahi hai. Product ka naam ya exact SKU bhejiye. Main chat mein policy, stock ya payment status guess nahi karungi.':'I do not have a verified answer to that yet. Try a product name or exact SKU. I will not guess a policy, stock level or payment status.';
}

const avatar='data:image/jpeg;base64,';
const css=' .mysa-root .chat{border:1px solid #d6e0ec;box-shadow:0 12px 36px #073a6a15;border-radius:20px;overflow:hidden;min-width:0;background:white} .mysa-root .chat-head{display:flex;gap:12px;align-items:center;padding:16px;background:#073d73;color:white} .mysa-root .chat-head img{width:44px;height:44px;border-radius:50%;object-fit:cover} .mysa-root .chat-head strong{display:block;font-size:18px} .mysa-root .chat-head small{display:block;opacity:.85;font-size:11px} .mysa-root .chat-head button{margin-left:auto;border:0;background:transparent;color:white;font-size:28px} .mysa-root .toolbar{display:flex;justify-content:space-between;gap:10px;padding:8px 12px;border-bottom:1px solid #ecf0f5} .mysa-root .toolbar button{border:0;font-size:12px;padding:0 10px} .mysa-root .toolbar button[aria-pressed=true]{background:#eaf2fb;font-weight:600} .mysa-root .log{height:300px;overflow:auto;padding:16px;display:flex;flex-direction:column;gap:12px;background:#f7f9fc} .mysa-root .bubble{padding:12px 14px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.55;max-width:90%;border-radius:14px} .mysa-root .bot{background:white;border:1px solid #e1e7ef;align-self:flex-start} .mysa-root .user{background:#0a4b84;color:white;align-self:flex-end} .mysa-root .chips{display:flex;flex-wrap:wrap;gap:6px;padding:12px} .mysa-root .chips button{font-size:11px;padding:6px 9px;border-radius:18px} .mysa-root .chat .composer{display:flex;gap:8px;padding:0 12px 12px} .mysa-root .chat input{width:100%;min-width:0;border:1px solid #d6e0ec;border-radius:10px;padding:10px 12px;font-size:13px} .mysa-root .chat .composer button{width:44px;flex-shrink:0;background:#f6a62b;color:#102f50;border:0;font-size:22px} .mysa-root .privacy{padding:0 12px 12px;font-size:10px;line-height:1.5;color:#69788b} .mysa-root .launcher{display:flex;align-items:center;justify-content:center;gap:12px;padding:10px 20px;background:#073d73;color:white;border-radius:40px} .mysa-root .launcher img{width:44px;height:44px;border-radius:50%} .mysa-root .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:760px){.demo{grid-template-columns:1fr;gap:20px}.intro{display:flex;gap:18px;align-items:center}.__unused{width:80px;height:80px;border-radius:18px;margin:0}.intro h2{font-size:21px;margin:8px 0}.intro p{font-size:12px}.intro .note{display:none} .mysa-root .chat{width:100%} .mysa-root .log{height:300px}.brand{font-size:10px}}\n\n.__unused{width:100%;height:auto;border-radius:14px;object-fit:contain} .mysa-root .chat-head img, .mysa-root .launcher img{object-fit:contain;border-radius:4px;width:62px;height:62px;background:white}@media(max-width:760px){.intro{display:block}.__unused{width:100%;height:auto;margin-bottom:16px}.intro .note{display:block}}\n .mysa-root button{cursor:pointer;font:inherit;min-height:44px;border:1px solid #d6e0ec;border-radius:8px;background:white;color:#103c6d}.mysa-root button:focus-visible,.mysa-root input:focus-visible{outline:3px solid #f1a129;outline-offset:3px}.mysa-root .chat-head button{background:transparent;color:white;border:0}.mysa-root .chat .composer button{background:#f6a62b}.mysa-root .panel{position:fixed;bottom:90px;right:20px;width:380px;max-height:calc(100dvh - 110px);overflow:auto;z-index:49}.mysa-root .launcher{position:fixed;bottom:20px;right:20px;z-index:49;background:#073d73;color:white}.mysa-root .full-photo{width:100%;height:auto;object-fit:contain;display:block}.mysa-root .disclosure{font-size:11px;line-height:1.5;padding:8px 12px;background:#fff6e8;color:#604000}.mysa-root button:disabled{opacity:.45}.mysa-root .log{height:220px}@media(max-width:500px){.mysa-root .panel{width:calc(var(--mysa-vw, 100vw) - 24px);right:12px;bottom:88px}.mysa-root .launcher{right:12px}}';
export const WhatsAppAIChat:React.FC<{onOpenVoice?:()=>void}>=()=>{
 const {products}=useStore();const [open,setOpen]=useState(false),[lang,setLang]=useState('en'),[input,setInput]=useState('');const welcome='Hi, I am MYSA, your UDECS shopping assistant. What are you looking for today?';const [messages,setMessages]=useState([{role:'bot',text:welcome}]);const log=useRef<HTMLDivElement>(null);
 useEffect(()=>{const update=()=>{document.documentElement.style.setProperty('--mysa-vw',`${window.visualViewport?.width||window.innerWidth}px`);document.documentElement.style.setProperty('--mysa-vh',`${window.visualViewport?.height||window.innerHeight}px`);document.documentElement.style.setProperty('--mysa-vx',`${window.visualViewport?.offsetLeft||0}px`);document.documentElement.style.setProperty('--mysa-vy',`${window.visualViewport?.offsetTop||0}px`)};update();window.visualViewport?.addEventListener('resize',update);window.visualViewport?.addEventListener('scroll',update);return()=>{window.visualViewport?.removeEventListener('resize',update);window.visualViewport?.removeEventListener('scroll',update)}},[]);
 useEffect(()=>{log.current?.scrollTo(0,log.current.scrollHeight)},[messages]);
 function send(text=input){if(!text.trim())return;setMessages(m=>[...m,{role:'user',text:text.trim().slice(0,500)},{role:'bot',text:reply(text,lang,products)}]);setInput('')}
 return <div className="mysa-root"><style>{css+ '.mysa-root .test-mysa-avatar{display:flex;width:44px;height:44px;flex-shrink:0;border-radius:50%;overflow:hidden;background:white;align-items:center;justify-content:center}.mysa-root .test-mysa-avatar img{width:70.7%;height:70.7%;object-fit:contain;padding:0}.mysa-root .launcher img{border-radius:50%;object-fit:contain;padding:9px;box-sizing:border-box;background:white}' + '@media(max-width:500px){.mysa-root .panel{left:calc(var(--mysa-vx, 0px) + 12px);right:auto;top:calc(var(--mysa-vy, 0px) + 12px);bottom:auto;width:calc(var(--mysa-vw, 100vw) - 24px);max-height:calc(var(--mysa-vh, 100dvh) - 112px)}.mysa-root .launcher{left:calc(var(--mysa-vx, 0px) + 12px);right:auto;top:calc(var(--mysa-vy, 0px) + var(--mysa-vh, 100dvh) - 96px);bottom:auto}}'}</style>{open&&<section className="panel chat" aria-label="MYSA chatbot"><header className="chat-head"><span className="test-mysa-avatar"><img src={avatar} alt="MYSA"/></span><div><strong>MYSA</strong><small>UDECS shopping assistant</small></div><button onClick={()=>setOpen(false)} aria-label="Close MYSA chat">×</button></header><img className="full-photo" src={avatar} alt="MYSA illustrated UDECS assistant"/><div className="disclosure">Product search + scripted replies. Order tracking coming soon. No AI model connected.</div><div className="toolbar"><div role="group" aria-label="Reply language"><button aria-pressed={lang==='en'} onClick={()=>setLang('en')}>English</button><button aria-pressed={lang==='hi'} onClick={()=>setLang('hi')}>हिन्दी</button></div><button onClick={()=>{setMessages([{role:'bot',text:welcome}]);setInput('')}}>Reset</button></div><div className="log" ref={log} role="log" aria-live="polite">{messages.map((m,i)=><div key={i} className={'bubble '+m.role}>{m.text}</div>)}</div><div className="chips">{['Find a blender','Track my order','Contact support'].map(q=><button key={q} onClick={()=>send(q)}>{q}</button>)}</div><div className="composer"><label className="sr" htmlFor="mysa-message">Your message</label><input id="mysa-message" value={input} maxLength={500} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();send()}}} placeholder="Ask about a product…"/><button type="button" onClick={()=>send()} disabled={!input.trim()} aria-label="Send MYSA message">↑</button></div><div className="privacy">Do not share passwords, OTPs or payment details. This chat is not saved; reload clears it.</div></section>}<button className="launcher" onClick={()=>setOpen(v=>!v)} aria-expanded={open}><img src={avatar} alt=""/>Chat with MYSA</button></div>
};
